            new Quote { Id = "https://en.wikiquote.org/wiki/Thomas_Jefferson", Text = "The most fortunate of us, in our journey through life, frequently meet with calamities and misfortunes which may greatly afflict us; and, to fortify our minds against the attacks of these calamities and misfortunes, should be one of the principal studies and endeavours of our lives.", Author = "Thomas Jefferson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Thomas_Jefferson", Text = "As to the species of exercise, I advise the gun. While this gives a moderate exercise to the body, it gives boldness, enterprise, and independence to the mind.", Author = "Thomas Jefferson" },
