            new Quote { Id = "https://en.wikiquote.org/wiki/Thomas_Jefferson", Text = "When a man assumes a public trust, he should consider himself as public property, and justly liable to the inspection and vigilance of public opinion...", Author = "Thomas Jefferson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Thomas_Jefferson", Text = "Can the liberties of a nation be thought secure when we have removed their only firm basis, a conviction in the minds of the people that these liberties are of the gift of God? That they are not to be violated but with his wrath? Indeed I tremble for my country when I reflect that God is just: that his justice cannot sleep forever.", Author = "Thomas Jefferson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Thomas_Jefferson", Text = "In a warm climate, no man will labour for himself who can make another labour for him. This is so true, that of the proprietors of slaves a very small proportion indeed are ever seen to labour.", Author = "Thomas Jefferson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Thomas_Jefferson", Text = "Manners and opinions change with the change of circumstances, institutions must advance also, and keep pace with the times. We might as well require a man to wear still the coat which fitted him when a boy, as civilized society to remain ever under the regimen of their barbarous ancestors. It is this preposterous idea which has lately deluged Europe in blood.", Author = "Thomas Jefferson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Thomas_Jefferson", Text = "Monarchs, instead of wisely yielding to the gradual change of circumstances, of favoring progressive accommodation to progressive improvement, have clung to old abuses, entrenched themselves behind steady habits, and obliged their subjects to seek through blood and violence rash and ruinous innovations, which, had they been referred to the peaceful deliberations and collected wisdom of the nation, would have been put into acceptable and salutary forms. Let us follow no such examples.", Author = "Thomas Jefferson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Thomas_Jefferson", Text = "A lively and lasting sense of filial duty is more effectually impressed on the mind of a son or daughter by reading King Lear, than by all the dry volumes of ethics, and divinity, that ever were written.", Author = "Thomas Jefferson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Thomas_Jefferson", Text = "The God who gave us life, gave us liberty at the same time; the hand of force may destroy, but cannot disjoin them.", Author = "Thomas Jefferson" },
