            new Quote { Id = "https://en.wikiquote.org/wiki/Thomas_Jefferson", Text = "Our cause is just. Our union is perfect. Our internal resources are great, and, if necessary, foreign assistance is undoubtedly attainable.", Author = "Thomas Jefferson" },
