            new Quote { Id = "https://en.wikiquote.org/wiki/Thomas_Jefferson", Text = "Truth will do well enough if left to shift for herself. She seldom has received much aid from the power of great men to whom she is rarely known & seldom welcome. She has no need of force to procure entrance into the minds of men. Error indeed has often prevailed by the assistance of power or force. Truth is the proper & sufficient antagonist to error.", Author = "Thomas Jefferson" },
