            new Quote { Id = "https://en.wikiquote.org/wiki/Thomas_Jefferson", Text = "I may grow rich by art I am compelled to follow, I may recover health by medicines I am compelled to take against my own judgment, but I cannot be saved by a worship I disbelieve & abhor.", Author = "Thomas Jefferson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Thomas_Jefferson", Text = "the opinions and belief of men depend not on their own will, but follow involuntarily the evidence proposed to their minds", Author = "Thomas Jefferson" },
