            new Quote { Id = "https://en.wikiquote.org/wiki/Thomas_Jefferson", Text = "I had rather be shut up in a very modest cottage with my books, my family and a few old friends, dining on simple bacon, and letting the world roll on as it liked, than to occupy the most splendid post, which any human power can give.", Author = "Thomas Jefferson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Thomas_Jefferson", Text = "I never submitted the whole system of my opinions to the creed of any party of men whatever in religion, in philosophy, in politics, or in anything else where I was capable of thinking for myself.", Author = "Thomas Jefferson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Thomas_Jefferson", Text = "Our liberty depends on the freedom of the press, and that cannot be limited without being lost.", Author = "Thomas Jefferson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Thomas_Jefferson", Text = "We took the liberty to make some enquiries concerning the ground of their pretension to make war upon nations who had done them no injury, and observed that we considered all mankind as our friends who had done us no wrong, nor had given us any provocation.", Author = "Thomas Jefferson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Thomas_Jefferson", Text = "The Ambassador answered us that it was founded on the Laws of their Prophet, that it was written in their Koran, that all nations who should not have acknowledged their authority were sinners, that it was their right and duty to make war upon them wherever they could be found, and to make slaves of all they could.", Author = "Thomas Jefferson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Thomas_Jefferson", Text = "The basis of our government being the opinion of the people, the very first object should be to keep that right; and were it left to me to decide whether we should have a government without newspapers, or newspapers without a government, I should not hesitate a moment to prefer the latter.", Author = "Thomas Jefferson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Thomas_Jefferson", Text = "every man should receive those papers and be capable of reading them.", Author = "Thomas Jefferson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Thomas_Jefferson", Text = "Experience declares that man is the only animal which devours his own kind; for I can apply no milder term to the governments of Europe, and to the general prey of the rich on the poor.", Author = "Thomas Jefferson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Thomas_Jefferson", Text = "I am convinced that those societies (as the Indians) which live without government enjoy in their general mass an infinitely greater degree of happiness than those who live under the European governments.", Author = "Thomas Jefferson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Thomas_Jefferson", Text = "I hold it, that a little rebellion, now and then, is a good thing, and as necessary in the political world as storms in the physical.", Author = "Thomas Jefferson" },
