            new Quote { Id = "https://en.wikiquote.org/wiki/Thomas_Jefferson", Text = "What country before ever existed a century and half without a rebellion? And what country can preserve its liberties if their rulers are not warned from time to time that their people preserve the spirit of resistance?", Author = "Thomas Jefferson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Thomas_Jefferson", Text = "When we get piled upon one another in large cities, as in Europe, we shall become corrupt as in Europe.", Author = "Thomas Jefferson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Thomas_Jefferson", Text = "I am not a friend to a very energetic government. It is always oppressive. It places the governors indeed more at their ease at the expense of the people.", Author = "Thomas Jefferson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Thomas_Jefferson", Text = "Virginia, I think, will be of this number. Besides other objections of less moment, she [Virginia] will insist on annexing a bill of rights to the new Constitution, i.e. a bill wherein the Government shall declare that, 1. Religion shall be free; 2. Printing presses free; 3. Trials by jury preserved in all cases; 4. No monopolies in commerce; 5. No standing army.", Author = "Thomas Jefferson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Thomas_Jefferson", Text = "Paper is poverty,... it is only the ghost of money, and not money itself.", Author = "Thomas Jefferson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Thomas_Jefferson", Text = "The natural progress of things is for liberty to yield, and government to gain ground.", Author = "Thomas Jefferson" },
