            new Quote { Id = "https://en.wikiquote.org/wiki/Thomas_Jefferson", Text = "I never submitted the whole system of my opinions to the creed of any party of men whatever in religion, in philosophy, in politics, or in anything else where I was capable of thinking for myself. Such an addiction is the last degradation of a free and moral agent.", Author = "Thomas Jefferson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Thomas_Jefferson", Text = "If I could not go to heaven but with a party, I would not go there at all.", Author = "Thomas Jefferson" },
